// back_inserter: O(1) amortized. Requires push_back().
// Optimized for vector/deque.
template <typename C>
class back_insert_iterator {
    C* container;
public:
    back_insert_iterator& operator*() { return *this; }
    back_insert_iterator& operator++() { return *this; }
    back_insert_iterator& operator=(
        const typename C::value_type& value) {
        container->push_back(value);
        return *this;
    }
};

// front_inserter: O(1). Requires push_front().
// Viable only for list/deque.
template <typename C>
class front_insert_iterator {
    C* container;
public:
    front_insert_iterator& operator*() { return *this; }
    front_insert_iterator& operator=(
        const typename C::value_type& value) {
        container->push_front(value);
        return *this;
    }
};

// inserter: Used for insertion at arbitrary position.
// Position is tracked and MUST be updated on assignment.
template <typename C, typename Pos>
class insert_iterator {
    C* container;
    Pos current_pos; // Location of NEXT insertion
public:
    insert_iterator& operator=(
        const typename C::value_type& value) {
        // Insert returns iterator pointing to new element
        current_pos = container->insert(current_pos, value);
        // Advance position for subsequent writes
        ++current_pos;
        return *this;
    }
    insert_iterator& operator*() { return *this; }
};
